// Generar fecha de hoy en formato ddmmaaaa (requerido por API Mercado Público)
const hoy = new Date();
const dd = String(hoy.getDate()).padStart(2, '0');
const mm = String(hoy.getMonth() + 1).padStart(2, '0');
const yyyy = hoy.getFullYear();

return [{
  json: {
    fecha_api: `${dd}${mm}${yyyy}`,
    fecha_iso: hoy.toISOString().split('T')[0],
    timestamp: hoy.toISOString()
  }
}];

// ═══════════════════════════════════════════════════════
// FILTRO INTELIGENTE + SCORING — JORGE DÍAZ
// Rubro: Ferretería industrial naval + buceo profesional
// ═══════════════════════════════════════════════════════

// Palabras clave de productos (ajustar según catálogo real)
const KEYWORDS_HOT = [
  'buceo', 'buzo', 'rebreather', 'regulador',
  'traje seco', 'traje humedo', 'wetsuit', 'drysuit',
  'compresor aire', 'banco aire', 'cilindro buceo',
  'umbilical', 'equipo subacu', 'hiperbarico'
];

const KEYWORDS_WARM = [
  'ferreteria naval', 'amarre', 'cabos', 'nautico',
  'maritimo', 'embarcacion', 'salvamento', 'chaleco salvavidas',
  'anclaje', 'cabullería', 'grillete', 'cornamusa'
];

// Organismos prioritarios (códigos Mercado Público)
const ORGANISMOS_VIP = {
  'ARMADA': 3,
  'DIRECTEMAR': 3,
  'DIRISNAV': 3,
  'GOPE': 2,
  'CARABINEROS': 2,
  'PORTUARIA': 2,
  'EPV': 2,
  'EPA': 2,
  'HIDRAULICA': 1,
  'INH': 1
};

const item = $json;

// Extraer campos clave (ajustar según estructura real de respuesta)
const codigo = item.CodigoExterno || '';
const nombre = (item.Nombre || '').toLowerCase();
const descripcion = (item.Descripcion || '').toLowerCase();
const organismo = (item.NombreOrganismo || '').toUpperCase();
const monto = parseFloat(item.MontoEstimado || 0);
const fechaCierre = item.FechaCierre || null;

const textoCompleto = `${nombre} ${descripcion}`;

// ─── SCORING ───
let score = 0;
let matches = [];
let categoria = 'cold';

// 1. Keywords hot (+15 cada uno, máx 45)
const hotCount = KEYWORDS_HOT.filter(k => textoCompleto.includes(k)).length;
score += Math.min(hotCount * 15, 45);
if (hotCount > 0) matches.push(`${hotCount} keyword(s) técnica(s)`);

// 2. Keywords warm (+8 cada uno, máx 24)
const warmCount = KEYWORDS_WARM.filter(k => textoCompleto.includes(k)).length;
score += Math.min(warmCount * 8, 24);
if (warmCount > 0) matches.push(`${warmCount} keyword(s) naval(es)`);

// 3. Organismo VIP
let organismoBoost = 0;
for (const [key, boost] of Object.entries(ORGANISMOS_VIP)) {
  if (organismo.includes(key)) {
    organismoBoost = Math.max(organismoBoost, boost * 10);
  }
}
score += organismoBoost;
if (organismoBoost > 0) matches.push('organismo VIP');

// 4. Monto (sweet spot $20M–$200M CLP)
if (monto >= 20000000 && monto <= 200000000) {
  score += 15;
  matches.push('monto sweet spot');
} else if (monto > 200000000) {
  score += 10;
  matches.push('monto alto');
} else if (monto >= 5000000) {
  score += 5;
}

// 5. Días al cierre — urgencia
let diasAlCierre = null;
if (fechaCierre) {
  const cierre = new Date(fechaCierre);
  const ahora = new Date();
  diasAlCierre = Math.ceil((cierre - ahora) / (1000 * 60 * 60 * 24));
  if (diasAlCierre > 0 && diasAlCierre <= 7) {
    score += 5;
    matches.push('cierra pronto');
  }
}

// Cap del score a 100
score = Math.min(score, 100);

// Clasificar
if (score >= 75) categoria = 'hot';
else if (score >= 45) categoria = 'warm';
else categoria = 'cold';

// Filtrar las que no aplican al negocio (score muy bajo O sin keywords)
if (score < 30 || (hotCount === 0 && warmCount === 0 && organismoBoost === 0)) {
  return []; // descartar
}

return [{
  json: {
    codigo_externo: item.CodigoExterno,
    nombre: item.Nombre,
    descripcion: item.Descripcion,
    organismo: item.NombreOrganismo,
    codigo_organismo: item.CodigoOrganismo,
    monto_estimado: monto,
    moneda: item.Moneda || 'CLP',
    fecha_publicacion: item.FechaPublicacion,
    fecha_cierre: item.FechaCierre,
    estado: item.CodigoEstado,
    tipo: item.Tipo,
    dias_al_cierre: diasAlCierre,
    score: score,
    categoria: categoria,
    matches: matches.join(', '),
    url_ficha: `https://www.mercadopublico.cl/Procurement/Modules/RFB/DetailsAcquisition.aspx?idlicitacion=${item.CodigoExterno}`,
    capturado_en: new Date().toISOString()
  }
}];
